package in.aicon.pocket;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import java.io.*;import java.lang.reflect.Constructor;import java.util.*;import java.util.concurrent.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="en-rIN-w432dp-h960dp-xxhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AccountUiTest {
 public static class CloudActivity extends QuickActivity {boolean cloudUiEnabled(){return true;}@Override LedgerController createLedgerController()throws Exception{return new LedgerController(this,this::runOnUiThread,(s,changed)->{if(changed){if(activeForm!=null)activeForm.dismiss();bindAccountSession();}if(page.equals("cloud")||changed)render();},Executors.newSingleThreadExecutor(),(s,t,a)->new SyncEngine.Result(0,0,0));}}
 CloudActivity activity;String subject="1234567890";
 VerifiedDriveAccess identity()throws Exception{Constructor<VerifiedDriveAccess> c=VerifiedDriveAccess.class.getDeclaredConstructor(String.class,String.class,String.class);c.setAccessible(true);return c.newInstance(subject,"sample@example.invalid","fake-test-token");}
 @Before public void setup(){try{androidx.work.WorkManager.getInstance(RuntimeEnvironment.getApplication());}catch(IllegalStateException init){androidx.work.WorkManager.initialize(RuntimeEnvironment.getApplication(),new androidx.work.Configuration.Builder().setMinimumLoggingLevel(android.util.Log.ERROR).build());}Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("hisab-account-directory",0).edit().clear().commit();for(String name:new String[]{"pocket.db",AccountScope.databaseFor(subject)})c.deleteDatabase(name);activity=Robolectric.buildActivity(CloudActivity.class).setup().get();}
 @After public void close(){if(activity!=null)activity.onDestroy();}
 void idle(){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 void shot(String name,View view)throws Exception{int w=1080,h=2400;view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));view.layout(0,0,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(QaArtifacts.file(name+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}}
 @Test public void localAndRememberedAccountScreensAndSeparateLedgerSwitch()throws Exception{activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));activity.page="cloud";activity.render();shot("cloud-local-screen",activity.root);activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();assertTrue(activity.session.accountLedger());assertEquals(0,activity.sum("SELECT count(*) FROM tx"));assertEquals("sample@example.invalid",activity.ledgerLabel());activity.page="cloud";activity.render();shot("cloud-account-screen",activity.root);activity.dark=true;activity.ml=true;activity.render();shot("cloud-account-dark-malayalam",activity.root);activity.ledgerController.selectLocal();idle();assertEquals(1,activity.sum("SELECT count(*) FROM tx"));assertFalse(activity.session.accountLedger());}
 @Test public void resetDialogCancelCannotClearMoneyAndNamesExpectedAccount()throws Exception{activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));activity.accountUi.confirmCloudReset();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();shot("cloud-reset-confirmation",dialog.getWindow().getDecorView());dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals(1,activity.sum("SELECT count(*) FROM tx"));assertFalse(activity.session.resetPending());}
 @Test public void oldResetConfirmationCannotResetDifferentSelectedLedger()throws Exception{activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();activity.accountUi.confirmCloudReset();AlertDialog old=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();activity.ledgerController.selectLocal();idle();assertFalse(old.isShowing());old.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(activity.session.accountLedger());assertFalse(activity.session.resetPending());}
 @Test public void conflictDescriptionShowsMoneyAsCurrencyNotMinorUnits()throws Exception{activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));LedgerSyncStore store=new LedgerSyncStore(activity.db,subject);SyncEngine.Snapshot snapshot=store.snapshot();SyncModel.Record record=null;for(SyncModel.Record r:snapshot.records.values())if(new JSONObject(r.payload).optString("type").equals("transaction"))record=r;assertNotNull(record);SyncModel.Conflict conflict=new SyncModel.Conflict(record.edit("left",new JSONObject(record.payload).put("note","A").toString(),false),record.edit("right",new JSONObject(record.payload).put("note","B").toString(),false));store.retainConflict(snapshot.revision,conflict);String description=activity.accountUi.describe(record,store.conflict());assertTrue(description,description.contains("123.00 INR"));assertFalse(description,description.contains("12300"));assertTrue(description,description.contains("Cash"));assertTrue(description,description.contains("Food"));}
 @Test public void disconnectConfirmationCancelKeepsAccountAndPermissionRequestUnstarted()throws Exception{activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();activity.accountUi.confirmDisconnect(subject,"sample@example.invalid");AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();shot("cloud-disconnect-confirmation",dialog.getWindow().getDecorView());dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals(subject,activity.ledgerController.status().subject);assertFalse(new AccountDirectory(activity).disconnectPending(subject));}
 @Test public void postedBackupActionAndReplacementTicketCannotCrossLedgerSwitchOrEdit()throws Exception{Object original=activity.actionTicket(),replacement=activity.replacementTicket();assertTrue(activity.actionCurrent(original));assertTrue(activity.actionCurrent(replacement));activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));assertTrue(activity.actionCurrent(original));assertFalse(activity.actionCurrent(replacement));activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();assertFalse(activity.actionCurrent(original));activity.postAction(original,()->fail());idle();}
 @Test public void replacementDialogCannotRestoreAfterNewLocalChanges()throws Exception{Object replacement=activity.replacementTicket();activity.mutate(()->LedgerSessionTest.transaction(activity.db,"income",12300,"",""));try{activity.requireAction(replacement);fail();}catch(IllegalStateException expected){}assertEquals(1,activity.sum("SELECT count(*) FROM tx"));}
 @Test public void documentPickerReturnFromClosedLedgerIsDiscarded()throws Exception{activity.saveFile("private-original-ledger".getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/csv","test.csv");Object original=activity.fileAction;assertTrue(activity.actionCurrent(original));activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();Intent result=new Intent();result.setData(android.net.Uri.parse("content://example.invalid/not-written"));activity.onActivityResult(activity.CREATE,Activity.RESULT_OK,result);assertNull(activity.pending);assertNull(activity.fileAction);}

 @Test public void repaymentReviewRendersOriginalDebtAndBothUnchosenPayments()throws Exception{activity.ledgerController.verified(identity());activity.ledgerController.selectKnown(subject);idle();String loan=UUID.randomUUID().toString(),left=UUID.randomUUID().toString(),right=UUID.randomUUID().toString();activity.mutate(()->{ContentValues v=new ContentValues();v.put("uuid",loan);v.put("kind","lent");v.put("amount",50000);v.put("day","2026-11-11");v.put("account","Cash");v.put("dest","");v.put("category","Debt");v.put("note","Original debt");v.put("person","Sample");v.put("loan","");activity.db.insertOrThrow("tx",null,v);});LedgerSyncStore store=new LedgerSyncStore(activity.db,subject);Map<String,SyncModel.Record> records=new TreeMap<>(store.snapshot().records);for(String id:new String[]{left,right})records.put(id,new SyncModel.Record(id,LedgerWire.transaction(id,"repay_in",30000,"2026-11-11","Cash","","Debt",id.equals(left)?"Device A payment":"Device B payment","Sample",loan).toString(),false,Collections.singletonMap(id.equals(left)?"left":"right",1L)));try{LedgerWire.validate(records);fail();}catch(LedgerIntegrity.RepaymentConflict issue){store.retainRepayment(store.snapshot().revision,records,issue);}activity.accountUi.reviewRepayments(store.repaymentReview());AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();shot("cloud-repayment-review",dialog.getWindow().getDecorView());dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals(1,activity.sum("SELECT count(*) FROM tx"));}

}
